from collections import deque

def solve(events):
    """FIFO stock ledger; O(n) rewrite of slow.solve."""
    held = {}
    val = {}
    tr = {}
    lots = {}
    realized = 0
    out = []
    for e in events:
        k = e[0]
        if k == 'buy':
            it = e[1]
            q = e[2]
            p = e[3]
            held[it] = held.get(it, 0) + q
            val[it] = val.get(it, 0) + q * p
            tr[it] = tr.get(it, 0) + 1
            b = lots.get(it)
            if b is None:
                lots[it] = deque(((q, p),))
            else:
                b.append((q, p))
        elif k == 'sell':
            it = e[1]
            q = e[2]
            p = e[3]
            tr[it] = tr.get(it, 0) + 1
            b = lots.get(it)
            if b is not None and q > 0:
                while q > 0 and b:
                    lot = b[0]
                    lq = lot[0]
                    lp = lot[1]
                    if q >= lq:
                        realized += lq * (p - lp)
                        q -= lq
                        held[it] -= lq
                        val[it] -= lq * lp
                        b.popleft()
                    else:
                        realized += q * (p - lp)
                        held[it] -= q
                        val[it] -= q * lp
                        b[0] = (lq - q, lp)
                        q = 0
        else:
            it = e[1]
            out.append([held.get(it, 0), val.get(it, 0), tr.get(it, 0), realized])
    return out

