    mts,i=M.rd(b,i);mgr,i=M.rd(b,i)
    mm=[None]*nc;mc=[None]*nc
    for j in range(nc):
        if kd[j]==NUM:
            m,i=M.rd(b,i);mm[j]=m
        if kd[j]==CAT:
            m,i=M.rd(b,i);mc[j]=m
    ft,i=GV(b,i)
    nst=[None]*nc
    for j in range(nc):
        if not nmi[j]:continue
        ch=[]
        for n in kc2:
            if not n:ch.append(None);continue
            f,i=GV(b,i);ch.append([UZ(f)])
        nst[j]=ch
    ng=mgr.t;nr=sum(kc2)
    dc2=Dc(b[i:])
    tsv=[ft]
    for g in range(1,ng):tsv.append(tsv[-1]+mts.v[dc2.get(mts.u,mts.c,mts.t)])
    mk=[mgr.v[dc2.get(mgr.u,mgr.c,mgr.t)]for _ in range(ng)]
    for j in range(nc):
        if not nmi[j]:continue
        m=mm[j]
        for s in range(len(kc2)):
            if nst[j][s] is None:continue
            vs=nst[j][s]
            for k in range(kc2[s]-1):vs.append(vs[-1]+m.v[dc2.get(m.u,m.c,m.t)])
    cst=[None]*nc;cp=[0]*nc;np_=[0]*nc
    for j in range(nc):
        if kd[j]==CAT:
            m=mc[j];cst[j]=[m.v[dc2.get(m.u,m.c,m.t)]for _ in range(nr)]
        if nmi[j]:np_[j]=[0]*len(kc2)
    o=[hd];rw=0
    for g in range(ng):
        for s in range(len(kc2)):
            if not(mk[g]>>s&1):continue
            f=[None]*nc
            for j in range(nc):
                k=kd[j]
                if k==GRP:f[j]=TXT(tsv[g])
                elif k==KEY:f[j]=dc[j][s]
                elif k==NUM:
                    p=np_[j][s];v=nst[j][s][p];np_[j][s]=p+1
                    if tf[j]:f[j]=TXT(v)
                    else:
                        mx,ex=nmi[j]
                        f[j]=ex[rw]if rw in ex else FMT(v,mx)
                else:
                    f[j]=dc[j][cst[j][cp[j]]];cp[j]+=1
            o.append(','.join(f));rw+=1
    return '\n'.join(o)+'\n'*tl

def compress(text):
    c=[]
    try:b=ST(text)
    except Exception:b=None
    if b:c.append(b)
    d=text.encode('utf-8')
    c.append(b'\x02'+lzma.compress(d,preset=9|lzma.PRESET_EXTREME,check=lzma.CHECK_NONE))
    c.append(b'\x03'+bz2.compress(d,9))
    c.append(b'\x04'+zlib.compress(d,9))
    return min(c,key=len)
def decompress(blob):
    t=blob[0]
    if t==1:return UN(blob)
    if t==2:return lzma.decompress(blob[1:]).decode('utf-8')
    if t==3:return bz2.decompress(blob[1:]).decode('utf-8')
    return zlib.decompress(blob[1:]).decode('utf-8')
